/// A consumer isolated to an actor: every value the SDK returns must cross the boundary.
actor DialogStore {
    private let client: TungoClient
    private(set) var titles: [String] = []
    private(set) var answer = ""

    init(client: TungoClient) {
        self.client = client
    }

    func refresh() async throws {
        let page = try await client.chat.list()
        titles = page.data.map { $0.title }
        for try await event in try await client.streamChat("hi") {
            if case .text(let text) = event { answer += text.delta }
        }
    }
}

